-- Performance Gym Co. V5 feature migration
create table if not exists public.pg_client_invites (id bigint generated by default as identity primary key, coach_id uuid not null references public.profiles(id) on delete cascade, client_name text not null, client_email text not null, program_name text, status text default 'pending', created_at timestamptz default now());
create table if not exists public.pg_workouts (id bigint generated by default as identity primary key, coach_id uuid not null references public.profiles(id) on delete cascade, title text not null, description text, category text, created_at timestamptz default now());
create table if not exists public.pg_golf_lessons (id bigint generated by default as identity primary key, coach_id uuid not null references public.profiles(id) on delete cascade, title text not null, focus text, drills text, created_at timestamptz default now());
create table if not exists public.pg_metrics (id bigint generated by default as identity primary key, user_id uuid not null references public.profiles(id) on delete cascade, name text not null, value text not null, unit text, category text, created_at timestamptz default now());
create table if not exists public.pg_video_submissions (id bigint generated by default as identity primary key, user_id uuid not null references public.profiles(id) on delete cascade, title text, file_path text, status text default 'submitted', coach_feedback text, created_at timestamptz default now());
create table if not exists public.pg_workout_logs (id bigint generated by default as identity primary key, user_id uuid not null references public.profiles(id) on delete cascade, workout_id bigint references public.pg_workouts(id) on delete set null, completed_at timestamptz default now());
create table if not exists public.pg_golf_logs (id bigint generated by default as identity primary key, user_id uuid not null references public.profiles(id) on delete cascade, lesson_id bigint references public.pg_golf_lessons(id) on delete set null, completed_at timestamptz default now());
create table if not exists public.pg_messages (id bigint generated by default as identity primary key, sender_id uuid not null references public.profiles(id) on delete cascade, recipient_id uuid not null references public.profiles(id) on delete cascade, body text not null, created_at timestamptz default now());
create or replace function public.is_coach(uid uuid) returns boolean language sql security definer set search_path=public stable as $$ select exists(select 1 from public.profiles where id=uid and role in ('coach','admin')); $$;

alter table public.pg_client_invites enable row level security;
alter table public.pg_workouts enable row level security;
alter table public.pg_golf_lessons enable row level security;
alter table public.pg_metrics enable row level security;
alter table public.pg_video_submissions enable row level security;
alter table public.pg_workout_logs enable row level security;
alter table public.pg_golf_logs enable row level security;
alter table public.pg_messages enable row level security;
do $$ declare r record; begin for r in select tablename,policyname from pg_policies where schemaname='public' and tablename like 'pg_%' loop execute format('drop policy if exists %I on public.%I',r.policyname,r.tablename); end loop; end $$;
create policy "coach manages invites" on public.pg_client_invites for all to authenticated using (public.is_coach(auth.uid())) with check (public.is_coach(auth.uid()));
create policy "coach manages workouts" on public.pg_workouts for all to authenticated using (public.is_coach(auth.uid())) with check (public.is_coach(auth.uid()));
create policy "authenticated reads workouts" on public.pg_workouts for select to authenticated using (true);
create policy "coach manages lessons" on public.pg_golf_lessons for all to authenticated using (public.is_coach(auth.uid())) with check (public.is_coach(auth.uid()));
create policy "authenticated reads lessons" on public.pg_golf_lessons for select to authenticated using (true);
create policy "users manage own metrics" on public.pg_metrics for all to authenticated using (auth.uid()=user_id or public.is_coach(auth.uid())) with check (auth.uid()=user_id or public.is_coach(auth.uid()));
create policy "users manage own videos" on public.pg_video_submissions for all to authenticated using (auth.uid()=user_id or public.is_coach(auth.uid())) with check (auth.uid()=user_id or public.is_coach(auth.uid()));
create policy "users manage own workout logs" on public.pg_workout_logs for all to authenticated using (auth.uid()=user_id or public.is_coach(auth.uid())) with check (auth.uid()=user_id or public.is_coach(auth.uid()));
create policy "users manage own golf logs" on public.pg_golf_logs for all to authenticated using (auth.uid()=user_id or public.is_coach(auth.uid())) with check (auth.uid()=user_id or public.is_coach(auth.uid()));
create policy "message participants" on public.pg_messages for all to authenticated using (auth.uid()=sender_id or auth.uid()=recipient_id or public.is_coach(auth.uid())) with check (auth.uid()=sender_id or public.is_coach(auth.uid()));
insert into storage.buckets (id,name,public) values ('client-videos','client-videos',false) on conflict (id) do nothing;
drop policy if exists "video uploads own folder" on storage.objects; create policy "video uploads own folder" on storage.objects for insert to authenticated with check (bucket_id='client-videos' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists "video reads own folder" on storage.objects; create policy "video reads own folder" on storage.objects for select to authenticated using (bucket_id='client-videos' and ((storage.foldername(name))[1]=auth.uid()::text or public.is_coach(auth.uid())));
